(() => {
'use strict';const $=s=>document.querySelector(s),core=window.GraphReading,NS='http://www.w3.org/2000/svg',number=x=>String(x).replace('.','{,}');
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}function circle(host,x,y,closed,color,r=5){const e=document.createElementNS(NS,'circle'),p=core.screen(x,y);for(const [key,value] of Object.entries({cx:p.x,cy:p.y,r,fill:closed?color:'#fafaf5',stroke:color,'stroke-width':2}))e.setAttribute(key,value);host.append(e);}
function draw(){const g=core.graphs.find(g=>g.id===$('#reading-graph').value),x=Number($('#reading-input').value),k=Number($('#reading-level').value),v=core.value(g,x),pre=core.preimage(g,k);$('#reading-input-output').value=String(x).replace('.',',');$('#reading-level-output').value=String(k).replace('.',',');math($('#reading-domain-range'),`D_f=${g.domain},\\quad R_f=${g.range}`);math($('#reading-value'),v===null?String.raw`f(${number(x)})\quad\text{tidak terdefinisi}`:`f(${number(x)})=${number(v)}`);$('#reading-value-feedback').textContent=v===null?'Masukan yang dipilih tidak termasuk domain. Tidak ada keluaran pada masukan ini; nilai fungsi bukan otomatis nol.':`Pada masukan ${String(x).replace('.',',')}, ketinggian grafik adalah ${String(v).replace('.',',')}.`;const solution=core.intervalTex(pre).replace(/(-?\d+)\.(\d+)/g,'$1{,}$2');math($('#reading-preimage'),`\\begin{gathered}f(x)=${number(k)}\\\\S=${solution}\\end{gathered}`);$('#reading-level-feedback').textContent=!pre.length?'Tidak ada masukan yang menghasilkan ketinggian ini.':pre.some(i=>i.lo<i.hi)?'Ada interval masukan yang seluruhnya menghasilkan ketinggian ini. Baca seluruh himpunan solusi, termasuk titik terpisah jika ada.':`Terdapat ${pre.length} masukan yang menghasilkan ketinggian ini.`;$('#reading-behavior').textContent='Perilaku: '+g.behavior;$('#reading-extrema').textContent='Ekstrem pada domain ini: '+g.extrema;let d='';g.nodes.forEach(([nx,ny],i)=>{const p=core.screen(nx,ny);d+=(i?'L':'M')+p.x+' '+p.y;});$('#reading-curve').setAttribute('d',d);const endpoints=$('#reading-endpoints');endpoints.replaceChildren();const first=g.nodes[0],last=g.nodes[g.nodes.length-1];circle(endpoints,...first,g.lc,'#2d674b');circle(endpoints,...last,g.hc,'#2d674b');const level=core.screen(0,k);$('#reading-level-line').setAttribute('d',`M50 ${level.y}H450`);const matches=$('#reading-matches');matches.replaceChildren();for(const i of pre){if(i.lo<i.hi){const path=document.createElementNS(NS,'path'),a=core.screen(i.lo,k),b=core.screen(i.hi,k);path.setAttribute('d',`M${a.x} ${a.y}L${b.x} ${b.y}`);path.setAttribute('stroke','#785497');path.setAttribute('stroke-width','6');matches.append(path);circle(matches,i.lo,k,i.lc,'#785497');circle(matches,i.hi,k,i.hc,'#785497');}else circle(matches,i.lo,k,true,'#785497',6);}const trial=$('#reading-trial'),projection=$('#reading-projections');trial.style.display=v===null?'none':'';projection.style.display=v===null?'none':'';if(v!==null){const p=core.screen(x,v);trial.setAttribute('cx',p.x);trial.setAttribute('cy',p.y);projection.setAttribute('d',`M250 ${p.y}H${p.x}M${p.x} 240V${p.y}`);}$('#reading-plot').setAttribute('aria-label',`Grafik lengkap pada domain. Masukan uji ${x}, ${v===null?'di luar domain':'keluaran '+v}. Garis ungu mencari keluaran ${k}; ${pre.length?'himpunan masukan ditulis di bawah grafik':'tidak ada masukan yang memenuhi'}.`);}
$('#reading-graph').addEventListener('change',draw);$('#reading-input').addEventListener('input',draw);$('#reading-level').addEventListener('input',draw);$('#reading-reset').addEventListener('click',()=>{$('#reading-graph').value='mixed';$('#reading-input').value=-2;$('#reading-level').value=1;draw();});draw();
const questions=[
[String.raw`f(-2)=?`,[String.raw`-2`,String.raw`3`,String.raw`-1`],1,'Pada masukan negatif dua, grafik utama mencapai ketinggian tiga. Jangan menukar masukan dan keluaran.'],
[String.raw`f(x)=1\quad\Longrightarrow\quad x\in?`,[String.raw`\{-3,0,2\}`,String.raw`\{-3\}\cup[0,2]`,String.raw`[0,2]`],1,'Selain masukan negatif tiga, seluruh ruas mendatar dari nol sampai dua memiliki keluaran satu. Bukan hanya kedua ujung ruas itu.'],
[String.raw`\text{Naik pada interval mana?}`,[String.raw`[-4,-2]`,String.raw`[-2,0]`,String.raw`[0,2]`],0,'Saat dibaca dari kiri ke kanan pada interval pertama, keluaran meningkat dari negatif satu sampai tiga.'],
[String.raw`\text{Nilai maksimum grafik utama?}`,[String.raw`-2`,String.raw`3`,String.raw`4`],1,'Nilai maksimum adalah keluaran tiga. Negatif dua adalah masukan tempat mencapainya.'],
[String.raw`\text{Masukan untuk minimum?}`,[String.raw`\{-1\}`,String.raw`\{-4,4\}`,String.raw`\{0,2\}`],1,'Nilai minimum negatif satu dicapai di kedua ujung domain, yaitu masukan negatif empat dan empat.'],
[String.raw`\text{Pada }[-2,0]\text{, fungsi utama ...}`,[String.raw`\text{Positif dan turun}`,String.raw`\text{Negatif dan turun}`,String.raw`\text{Positif dan naik}`],0,'Keluaran turun dari tiga ke satu, tetapi semuanya masih positif. Positif dan naik adalah dua informasi berbeda.'],
[String.raw`\text{Garis dengan ujung terbuka ...}`,[String.raw`\text{Maksimum tiga}`,String.raw`\text{Tidak ada keduanya}`,String.raw`\text{Minimum negatif satu}`],1,'Tiga dan negatif satu tidak dicapai. Setiap keluaran yang dicapai masih memiliki keluaran lain yang lebih besar atau lebih kecil.'],
[String.raw`f(x)=1,\quad -4\le x\le4`,[String.raw`\text{Semua masukan ekstrem}`,String.raw`\text{Hanya nol yang ekstrem}`,String.raw`\text{Tidak ada ekstrem}`],0,'Pada fungsi konstan, setiap masukan pada domain mencapai nilai maksimum dan minimum yang sama, yaitu satu.']
];const solved=new Set();questions.forEach(([tex,options,answer,reason],i)=>{const box=document.createElement('fieldset'),legend=document.createElement('legend'),num=document.createElement('span'),formula=document.createElement('span');num.dataset.noEquation='';num.textContent=`Latihan ${i+1}: `;formula.dataset.tex=tex;legend.append(num,formula);box.append(legend);options.forEach((option,j)=>{const label=document.createElement('label'),radio=document.createElement('input'),copy=document.createElement('span');radio.type='radio';radio.name=`reading-q${i}`;radio.value=String(j);copy.dataset.tex=option;label.append(radio,copy);box.append(label);});const button=document.createElement('button');button.type='button';button.textContent='Periksa jawaban';const feedback=document.createElement('p');feedback.setAttribute('role','status');button.addEventListener('click',()=>{const selected=box.querySelector('input:checked');if(!selected){feedback.textContent='Pilih satu jawaban terlebih dahulu.';return;}const ok=Number(selected.value)===answer;if(ok)solved.add(i);feedback.textContent=(ok?'Tepat. ':'Belum tepat. ')+reason;feedback.className=ok?'correct':'incorrect';$('#reading-progress').textContent=`${solved.size} dari 8 latihan pernah dijawab tepat.`;});box.addEventListener('change',()=>{feedback.textContent='Jawaban berubah. Periksa kembali untuk melihat tanggapan.';feedback.className='';});box.append(button,feedback);$('#reading-questions').append(box);});$('#reading-progress').textContent='0 dari 8 latihan pernah dijawab tepat.';
try{$('#reading-reflection').value=localStorage.getItem('fondasi-graph-reading-reflection')||'';}catch{$('#reading-save').textContent='Catatan belum dapat dimuat. Salin bila diperlukan.';}$('#reading-reflection').addEventListener('input',()=>{try{localStorage.setItem('fondasi-graph-reading-reflection',$('#reading-reflection').value);$('#reading-save').textContent='Catatan tersimpan di peramban ini.';}catch{$('#reading-save').textContent='Catatan belum dapat disimpan. Salin bila diperlukan.';}});
})();
